#!/usr/bin/env python3
# =====================================================================
#  apply_wing_reach.py  —  fence WING_REACH_20261111
#  REQUIRES apply_tsg_wing_guard.py (TSG_WING_GUARD_20261111) first.
#
#  Fleet follow-up to the 11-Nov Tigris missing-wing incident. Every core
#  strategy that buys a hedge searched only spot ± 1500, and on 3–5-session
#  days the ₹3–5 hedges sit beyond it (put skew). None of them ever traded
#  bare, but each handled it quietly:
#
#   IC_V1/IC_V2  wing ₹4: took the cheapest strike INSIDE ±1500 (dearer,
#                closer than configured) — a flag on the leg, no alert.
#                → ic_engine.py: entry + adjustment chain at ±3000
#                  (cfg chain_strike_range); ic_group_manager.py:
#                  IC_WING_FALLBACK warning; IC_WING_ABSENT now an error
#                  that also reaches Telegram when LIVE.
#   TMA_V2       hedge ₹5: same cheapest-in-band fallback, audit log only.
#                → tma2_tick_engine.py BAND_STRIKES 30 → 60 (±3000);
#                  tma2_trade_manager.py: TMA2_HEDGE_FALLBACK warning,
#                  TMA2_HEDGE_MISSING error when a signal is skipped.
#   VET_V1       wing ₹3: already never bare + far-wing search (1 Nov),
#                but a skipped entry was audit log only. Shares the TMA2
#                tick engine, so it gets ±3000 too (fewer far searches).
#                → vet_manager.py: VET_WING_MISSING error, once per side
#                  per day (each 5-min retry still goes to the log).
#   tests        test_wing_reach.py (17 checks, replays the 11-Nov chain
#                for Icarus), ic/test_ic_wing_reach.py (3 pytest cases)
#
#  Paper alerts stay in the bell (CRITICAL_ALERT_ROUTING). Picks on a
#  normal day are unchanged: "highest premium <= cap" lands on the same
#  contract; the wider band only adds cheaper strikes further out.
#  ORB/BRK/EMC/GC (premium buyers, no wings) keep ±1500 on purpose.
#  No new sockets: TMA2 and VET each go from ~122 to ~242 contracts on
#  their existing one (Kite allows 3000 per socket).
#
#  Run ONLY this script, outside market hours (Timberwolf/Velvet sockets
#  pick the band up at their next boot):
#     cd ~/dev/scalp-app && python3 apply_wing_reach.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "WING_REACH_20261111"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/ic/ic_engine.py", "orig": "13414814137e3e68b6ca0f087175ae669b43fcdf192fae146c7e01425c4aa2b7", "new": "28bbdb9be64d2c70c450e0cded71dc7173bc333c8baf80f497be7d1485bbd56a", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "cbb245824df3983bbe8be81dbead0beaf0294ab80682c9dd3cc3719ef934bc6a", "new": "95e83dbda4dd4b8ee9cf505e662b525d75cb6ab2fbbb51dec91b037712bb3a6b", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_tick_engine.py", "orig": "d5f0816292e346afd195cd7343a05e578f97db98aa3ef4aad6e07aedad73a685", "new": "d2b4463638d9ca095ee1e91142125c9dd76786214b8435929fb1e54bbd5fc398", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "6e8167b53623d166a6678a2ff5174a730dcc7bade5a7c530e22ae664501dbe11", "new": "b0df002a50d736f2ed7a98611ca7231cae4150e28d493f0c4ae2dbe09530f5db", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "11779e0e9ce0eda25dcf606257b1f3a319c110f794c83338697fbd1a3467f091", "new": "2bf09d89bf61c91b7b2f18316fb0d61e1ae01a7508e857aea377785535e57d71", "blob": ""}, {"path": "backend/app/engine/test_wing_reach.py", "orig": null, "new": "7dee038b77b896b343e0f2b836696eaf7bb2884291f1b114e74d2e19c256cfcb", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_wing_reach.py", "orig": null, "new": "4b3db0aeb42c276c48360aa6fb34b23fc205a737e39eb4ecdd48d16c40368bad", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/engine/test_wing_reach.py", "app/engine/ic/test_ic_wing_reach.py",
         "app/engine/ic/test_ic2_shadow_carry.py",
         "app/engine/tma2/test_tma2_e2e.py", "app/engine/tma2/test_tma2_entry_paths.py",
         "app/engine/tma2/test_tma2_exit_paths.py", "app/engine/tma2/test_tma_paper_fallback.py",
         "app/engine/tma2/test_tick_ltp_publish.py",
         "app/engine/vet/test_vet_e2e.py", "app/engine/vet/test_vet_manager.py",
         "app/engine/vet/test_vet_wing_far.py", "app/engine/vet/test_vet_wing_search.py",
         "app/engine/vet/test_vet_live_confirm.py", "app/engine/vet/test_vet_near_obs.py",
         "app/engine/tsg/test_tsg_wing_guard.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: TSG_WING_GUARD_20261111 (adds strike_range to the chain snapshot)
_icsel = os.path.join(repo, "backend", "app", "engine", "ic", "ic_selection.py")
if "--rollback" not in args and "TSG_WING_GUARD_20261111" not in open(_icsel, encoding="utf-8").read():
    die("apply_tsg_wing_guard.py first — this script builds on TSG_WING_GUARD_20261111")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="wing_reach_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_wing_reach.py --rollback")
